            ['start_time' => 365.68, 'end_time' => 371.58, 'target_text' => 'And once in a while, I spray my throat because we talk a lot and it becomes dry.', 'source_text' => 'Sekali-sekala saya menyemburkannya ke dalam tekak kerana kami banyak berceramah sehingga tekak menjadi kering.', 'order' => 87],
