            ['start_time' => 393.36, 'end_time' => 395.42, 'target_text' => 'So like I said we deal with recklessness.', 'source_text' => 'Maka seperti yang saya katakan, pihak berkuasa sedang menangani pemanduan melulu.', 'order' => 93],
            ['start_time' => 395.52, 'end_time' => 398.3, 'target_text' => 'They were dealing with it by stopping everyone and testing them.', 'source_text' => 'Mereka bertindak dengan menahan dan menguji setiap pemandu.', 'order' => 94],
