            ['start_time' => 404.48, 'end_time' => 405.74, 'target_text' => 'And he says can you breathe in?', 'source_text' => 'Pegawai itu berkata: "Boleh hembuskan nafas ke dalam alat ini?"', 'order' => 99],
            ['start_time' => 405.84, 'end_time' => 408.06, 'target_text' => 'First time in my life I\'m looking at a breathalyzer.', 'source_text' => 'Sepanjang hidup saya, itulah kali pertama saya melihat alat ujian alkohol tersebut di depan mata!', 'order' => 100],
