            ['start_time' => 409.04, 'end_time' => 412.46, 'target_text' => 'It\'s the size of two of two mobile phones put together with a little gadget.', 'source_text' => 'Saiznya seperti dua buah telefon bimbit yang dicantumkan bersama dengan satu gajet kecil.', 'order' => 102],
