            ['start_time' => 492.96, 'end_time' => 496.62, 'target_text' => '"Yes, we can do a blood test, but we have to go to the police station." I said, "No problem.', 'source_text' => '"Ya, kita boleh buat ujian darah, tetapi kita perlu ke balai polis." Saya kata, "Tiada masalah.', 'order' => 130],
