            ['start_time' => 560.64, 'end_time' => 561.18, 'target_text' => 'come on, man.', 'source_text' => 'fikirlah secara waras.', 'order' => 147],
            ['start_time' => 561.28, 'end_time' => 568.54, 'target_text' => 'Do you really think I drink?" So, by that time, I didn\'t have any taste of this throat spray in my mouth.', 'source_text' => 'Adakah kamu benar-benar fikir saya minum arak?" Menjelang waktu itu, rasa semburan tekak itu sudah hilang sepenuhnya dari mulut saya.', 'order' => 148],
            ['start_time' => 568.64, 'end_time' => 571.02, 'target_text' => 'It was maybe about 5 7 minutes.', 'source_text' => 'Ia sudah berlalu sekitar 5 hingga 7 minit.', 'order' => 149],
