            ['start_time' => 612.16, 'end_time' => 616.3, 'target_text' => 'But to be honest, let\'s not talk about corruption because that\'s not the topic today.', 'source_text' => 'Tetapi secara jujurnya, janganlah kita bercakap tentang rasuah kerana itu bukan tajuk kita pada hari ini.', 'order' => 166],
            ['start_time' => 616.4, 'end_time' => 618.94, 'target_text' => 'It is going to be dealt with inshallah.', 'source_text' => 'Perkara itu akan diselesaikan pada masa lain insya-Allah.', 'order' => 167],
            ['start_time' => 619.04, 'end_time' => 621.26, 'target_text' => 'It has to be spoken about, but not today.', 'source_text' => 'Ia memang perlu dibincangkan, tetapi bukan hari ini.', 'order' => 168],
            ['start_time' => 621.36, 'end_time' => 631.5, 'target_text' => 'But today, I want everyone to go home and remember that what you stand for as a Muslim is when you differ with someone, disagree', 'source_text' => 'Tetapi hari ini, saya mahu semua orang pulang ke rumah dan ingat bahawa prinsip kita sebagai orang Islam adalah apabila kita berbeza pandangan atau berselisih faham,', 'order' => 169],
            ['start_time' => 631.6, 'end_time' => 636.54, 'target_text' => 'with them, have a problem with them, you have to offer them minimum respect.', 'source_text' => 'dengan seseorang, atau ada masalah dengan mereka, anda tetap wajib memberikan penghormatan yang sewajarnya kepada mereka.', 'order' => 170],
            ['start_time' => 636.64, 'end_time' => 638.78, 'target_text' => 'You don\'t become abusive and vulgar.', 'source_text' => 'Jangan sesekali menjadi orang yang suka mencaci dan bersikap biadab.', 'order' => 171],
            ['start_time' => 638.88, 'end_time' => 645.98, 'target_text' => 'You know in the Quran Allah speaks about the beggars and I love the verse because for me it brings me a great lesson.', 'source_text' => 'Tahukah anda di dalam Al-Quran Allah berfirman mengenai peminta sedekah dan saya sangat menyukai ayat itu kerana ia memberi pengajaran yang sangat besar.', 'order' => 172],
            ['start_time' => 646.08, 'end_time' => 648.62, 'target_text' => 'It has improved me whenever I think about it.', 'source_text' => 'Ia sentiasa mendidik dan memperbaiki diri saya setiap kali saya merenunginya.', 'order' => 173],
            ['start_time' => 648.72, 'end_time' => 652.3, 'target_text' => 'Allah says as for the beggar do not rebuke him.', 'source_text' => 'Allah berfirman: dan adapun orang yang meminta sedekah, maka janganlah engkau mengherdik atau menengkingnya.', 'order' => 174],
            ['start_time' => 652.4, 'end_time' => 653.42, 'target_text' => 'Don\'t abuse him.', 'source_text' => 'Jangan caci atau maki dia.', 'order' => 175],
            ['start_time' => 653.52, 'end_time' => 656.78, 'target_text' => 'In this masid is called mid.', 'source_text' => 'Di dalam surah ad-Dhuha ini, perkataan yang digunakan ialah \'tanhar\'.', 'order' => 176],
            ['start_time' => 656.88, 'end_time' => 659.24, 'target_text' => 'Let\'s take the lesson.', 'source_text' => 'Marilah kita mengambil pengajaran daripadanya.', 'order' => 177],
            ['start_time' => 663.2, 'end_time' => 665.58, 'target_text' => 'As for the beggar, don\'t rebuke him.', 'source_text' => 'Adapun terhadap peminta sedekah, janganlah kamu mengherdik mereka.', 'order' => 178],
            ['start_time' => 665.68, 'end_time' => 666.46, 'target_text' => 'Don\'t abuse him.', 'source_text' => 'Jangan berkasar dengan mereka.', 'order' => 179],
            ['start_time' => 666.56, 'end_time' => 667.42, 'target_text' => 'Don\'t insult him.', 'source_text' => 'Jangan menghina mereka.', 'order' => 180],
            ['start_time' => 667.52, 'end_time' => 668.38, 'target_text' => 'Don\'t belittle him.', 'source_text' => 'Jangan merendah-rendahkan mereka.', 'order' => 181],
            ['start_time' => 668.48, 'end_time' => 670.62, 'target_text' => 'All of that is included in falat.', 'source_text' => 'Semua larangan itu terkandung di dalam perkataan \'fa la tanhar\'.', 'order' => 182],
            ['start_time' => 670.72, 'end_time' => 674.94, 'target_text' => 'Allah didn\'t tell you when a beggar is begging, give him because that\'s your choice.', 'source_text' => 'Allah tidak mewajibkan anda memberi setiap kali peminta sedekah meminta, kerana itu adalah pilihan anda sendiri.', 'order' => 183],
            ['start_time' => 675.04, 'end_time' => 676.54, 'target_text' => 'You can give him or not give him.', 'source_text' => 'Anda boleh memilih untuk memberinya atau tidak memberinya.', 'order' => 184],
            ['start_time' => 676.64, 'end_time' => 679.66, 'target_text' => 'Some of the beggars are part of a larger scam.', 'source_text' => 'Sesetengah peminta sedekah adalah sebahagian daripada sindiket penipuan yang besar.', 'order' => 185],
            ['start_time' => 679.76, 'end_time' => 683.58, 'target_text' => 'Some of them make more money than you and I working 8 to 5.', 'source_text' => 'Sesetengah mereka mengaut pendapatan lebih lumayan berbanding kita yang bekerja dari pukul 8 pagi hingga 5 petang.', 'order' => 186],
            ['start_time' => 683.68, 'end_time' => 685.98, 'target_text' => 'And it\'s it\'s okay for you to doubt.', 'source_text' => 'Dan tidak salah untuk anda berasa ragu-ragu.', 'order' => 187],
            ['start_time' => 686.08, 'end_time' => 688.06, 'target_text' => 'But I can\'t insult.', 'source_text' => 'Tetapi saya sama sekali tidak boleh menghina mereka.', 'order' => 188],
            ['start_time' => 688.16, 'end_time' => 690.86, 'target_text' => 'If you are not going to give,', 'source_text' => 'Jika anda tidak berniat untuk memberi,', 'order' => 189],
            ['start_time' => 690.96, 'end_time' => 693.66, 'target_text' => 'turn away respectfully without insulting.', 'source_text' => 'berlalulah dengan sopan dan penuh hormat tanpa menghina.', 'order' => 190],
            ['start_time' => 693.76, 'end_time' => 694.7, 'target_text' => 'Can you do that?', 'source_text' => 'Bolehkah anda lakukan perkara itu?', 'order' => 191],
            ['start_time' => 694.8, 'end_time' => 699.82, 'target_text' => 'It says a lot about you as a Muslim how you react to a beggar.', 'source_text' => 'Cara anda melayan peminta sedekah mencerminkan keperibadian sebenar anda sebagai seorang Muslim.', 'order' => 192],
            ['start_time' => 699.92, 'end_time' => 707.98, 'target_text' => 'It says a lot about you as a Muslim how you treat those whom you perceive as from a lower class than yours simply because', 'source_text' => 'Ia mencerminkan peribadi anda sebagai orang Islam dalam cara anda melayan mereka yang anda anggap berstatus lebih rendah hanya kerana', 'order' => 193],
            ['start_time' => 708.08, 'end_time' => 712.86, 'target_text' => 'of your own perception and understanding which is warped.', 'source_text' => 'tanggapan dan persepsi peribadi anda sendiri yang mungkin terpesong.', 'order' => 194],
            ['start_time' => 712.96, 'end_time' => 718.54, 'target_text' => 'You look at someone and you think look at this guy who does he think he is that guy could turn out being a person who\'s going', 'source_text' => 'Anda memandang seseorang dan berfikir siapakah dia ini, padahal individu itulah yang mungkin ditakdirkan', 'order' => 195],
            ['start_time' => 718.64, 'end_time' => 720.06, 'target_text' => 'to solve your problems.', 'source_text' => 'untuk membantu menyelesaikan masalah anda.', 'order' => 196],
            ['start_time' => 720.16, 'end_time' => 723.18, 'target_text' => 'I remember one of the borders I was stuck at some years ago.', 'source_text' => 'Saya teringat ketika saya terkandas di salah sebuah pintu sempadan beberapa tahun yang lalu.', 'order' => 197],
            ['start_time' => 723.28, 'end_time' => 729.98, 'target_text' => 'I spoke about it and Juma they told me you can\'t cross because I had a Zimbabwean passport and that\'s the only passport I', 'source_text' => 'Saya pernah ceritakan perkara ini dalam khutbah Jumaat, mereka beritahu saya tidak boleh melintas kerana pasport Zimbabwe saya dan itulah satu-satunya pasport yang', 'order' => 198],
            ['start_time' => 730.08, 'end_time' => 730.31, 'target_text' => 'have.', 'source_text' => 'saya miliki.', 'order' => 199],
            ['start_time' => 730.32, 'end_time' => 737.18, 'target_text' => 'So basically they told me you need a visa to go but I said last week I was here they said no the rule changed this week now', 'source_text' => 'Jadi pada asasnya mereka beritahu saya memerlukan visa, tetapi saya kata minggu lepas saya boleh lalu, mereka kata peraturan telah bertukar minggu ini', 'order' => 200],
            ['start_time' => 737.28, 'end_time' => 737.74, 'target_text' => 'I\'m stuck.', 'source_text' => 'Saya terkandas.', 'order' => 201],
            ['start_time' => 737.84, 'end_time' => 746.94, 'target_text' => 'It was Friday Jum and we came in and a guy greeted me and he sat down and I sat next to him and mashallah the imam was talking', 'source_text' => 'Ketika itu hari Jumaat untuk solat Jumaat, kami masuk dan seorang lelaki memberi salam kepada saya, dia duduk dan saya duduk di sebelahnya, dan masya-Allah imam sedang bercakap', 'order' => 202],
            ['start_time' => 747.04, 'end_time' => 752.54, 'target_text' => 'about helping people and solving problems and so on and you know you are not true believers until you love for your brother', 'source_text' => 'tentang membantu orang lain, menyelesaikan masalah dan sebagainya, serta peringatan bahawa tidak sempurna iman seseorang sehingga dia mengasihi saudaranya', 'order' => 203],
            ['start_time' => 752.64, 'end_time' => 758.54, 'target_text' => 'what you love for yourself and you must assist and help and after the salah I said let me try one more time so there was a', 'source_text' => 'seperti dia mengasihi dirinya sendiri dan kewajipan saling membantu. Selepas solat, saya berkata biarlah saya mencuba sekali lagi, lalu di situ ada seorang', 'order' => 204],
            ['start_time' => 758.64, 'end_time' => 763.9, 'target_text' => 'cleaner I said you know what I have a problem where\'s the manager the main boss here she said you know that office inside', 'source_text' => 'pekerja pembersihan, saya bertanya, "Saya ada masalah, di manakah pejabat pengurus atau ketua utama di sini?" Dia menjawab, "Anda nampak pejabat di sebelah dalam', 'order' => 205],
            ['start_time' => 764.0, 'end_time' => 767.5, 'target_text' => 'there there\'s a guy sitting there but you can\'t go in.', 'source_text' => 'sana? Ada seorang pegawai duduk di situ, tetapi anda tidak boleh masuk.', 'order' => 206],
            ['start_time' => 767.6, 'end_time' => 769.74, 'target_text' => 'But never mind, I\'ll let you in.', 'source_text' => 'Tetapi tidak mengapalah, saya akan benarkan anda masuk."', 'order' => 207],
            ['start_time' => 769.84, 'end_time' => 770.23, 'target_text' => 'Wow.', 'source_text' => 'Hebat.', 'order' => 208],
            ['start_time' => 770.24, 'end_time' => 771.26, 'target_text' => 'I went in.', 'source_text' => 'Saya pun masuk ke dalam.', 'order' => 209],
            ['start_time' => 771.36, 'end_time' => 772.06, 'target_text' => 'Knock knock knock.', 'source_text' => 'Tok, tok, tok.', 'order' => 210],
            ['start_time' => 772.16, 'end_time' => 774.3, 'target_text' => 'The guy says, "Open the door.', 'source_text' => 'Pegawai itu berkata, "Buka pintu.', 'order' => 211],
            ['start_time' => 774.4, 'end_time' => 775.5, 'target_text' => 'Open the door." Who was it?', 'source_text' => 'Buka pintunya." Dan siapakah orang itu?', 'order' => 212],
            ['start_time' => 775.6, 'end_time' => 777.9, 'target_text' => 'The guy sitting next to me in prayers.', 'source_text' => 'Rupa-rupanya lelaki yang duduk di sebelah saya semasa solat tadi.', 'order' => 213],
            ['start_time' => 778.0, 'end_time' => 779.9, 'target_text' => 'He looked and I had greeted him and that\'s it.', 'source_text' => 'Dia memandang saya, dan sebelum ini saya cuma sempat memberi salam kepadanya sahaja.', 'order' => 214],
            ['start_time' => 780.0, 'end_time' => 782.7, 'target_text' => 'And he greeted me and I told him, "Habibi, I have a problem.', 'source_text' => 'Dia menyambut salam saya dan saya beritahu kepadanya, "Wahai sahabatku, saya ada masalah.', 'order' => 215],
            ['start_time' => 782.8, 'end_time' => 783.98, 'target_text' => 'This is the issue." He said, "No problem.', 'source_text' => 'Inilah masalahnya." Dia menjawab, "Tiada masalah langsung.', 'order' => 216],
            ['start_time' => 784.08, 'end_time' => 788.12, 'target_text' => 'My le I\'ll give it to you now." He wrote in Arabic.', 'source_text' => 'Saya akan berikan kelulusan kepada anda sekarang juga." Lalu dia menulis dalam bahasa Arab.', 'order' => 217],
            ['start_time' => 788.4, 'end_time' => 790.46, 'target_text' => 'He says, "We\'ve given him a verbal visa.', 'source_text' => 'Dia menyatakan, "Kami telah memberikannya visa lisan.', 'order' => 218],
            ['start_time' => 790.56, 'end_time' => 798.06, 'target_text' => 'I I I\'ve never heard of that in my life." And I thought to myself, just imagine how Allah has told us to respect each other,', 'source_text' => 'Seumur hidup saya, saya tidak pernah mendengar istilah visa lisan." Dan saya berfikir sendiri, bayangkan betapa Allah menyuruh kita saling menghormati,', 'order' => 219],
            ['start_time' => 798.16, 'end_time' => 804.54, 'target_text' => 'to offer a minimum, you know, that what you owe a believer is assalamu alaykum habibi.', 'source_text' => 'untuk sekurang-kurangnya memberi hak sesama orang beriman iaitu ucapan: assalamu\'alaikum wahai sahabatku.', 'order' => 220],
            ['start_time' => 804.64, 'end_time' => 806.38, 'target_text' => 'That means peace be upon you.', 'source_text' => 'Maksudnya ialah semoga kesejahteraan dilimpahkan ke atas anda.', 'order' => 221],
            ['start_time' => 806.48, 'end_time' => 808.06, 'target_text' => 'I\'m not going to harm you.', 'source_text' => 'Aku tidak akan sesekali memudaratkan atau menyakiti kamu.', 'order' => 222],
            ['start_time' => 808.16, 'end_time' => 810.7, 'target_text' => 'My brothers and sisters, the um is bleeding.', 'source_text' => 'Wahai saudara-saudariku, umat Islam hari ini sedang berdarah dan terluka.', 'order' => 223],
            ['start_time' => 810.8, 'end_time' => 816.62, 'target_text' => 'I\'d like to think one of the reasons why the victory is being delayed is our hearts are not where they supposed to be.', 'source_text' => 'Saya berpendapat salah satu punca mengapa kemenangan dilengahkan adalah kerana hati kita tidak berada di tempat yang sepatutnya.', 'order' => 224],
            ['start_time' => 816.72, 'end_time' => 818.46, 'target_text' => 'They\'re in the wrong place.', 'source_text' => 'Hati kita berada di tempat yang salah.', 'order' => 225],
            ['start_time' => 818.56, 'end_time' => 819.74, 'target_text' => 'You have issues, no problem.', 'source_text' => 'Anda ada perselisihan pendapat, itu lumrah dan tiada masalah.', 'order' => 226],
            ['start_time' => 819.84, 'end_time' => 823.98, 'target_text' => 'But if your brother is dying or has suffered, are you going to say he deserves it?', 'source_text' => 'Tetapi jika saudara anda sedang mati atau dizalimi, tergamakkah anda berkata bahawa dia memang layak menerimanya?', 'order' => 227],
            ['start_time' => 824.08, 'end_time' => 827.5, 'target_text' => 'If that\'s the case, when you are struggling, they will say you deserve it.', 'source_text' => 'Jika demikian sikap kita, maka apabila anda pula yang ditimpa kesusahan, orang lain juga akan berkata anda layak menerimanya.', 'order' => 228],
            ['start_time' => 827.6, 'end_time' => 830.54, 'target_text' => 'And in that particular instance, guess what will happen?', 'source_text' => 'Dan dalam keadaan sedemikian, teka apa yang akan berlaku?', 'order' => 229],
            ['start_time' => 830.64, 'end_time' => 837.1, 'target_text' => 'The enemy who wants to destroy us collectively is having fun because we\'re doing a better job than he could ever have done.', 'source_text' => 'Musuh yang berniat memusnahkan kita secara keseluruhan bersenang-lenang kerana kita sendiri telah memusnahkan diri kita lebih teruk daripada apa yang mereka mampu lakukan.', 'order' => 230],
            ['start_time' => 837.2, 'end_time' => 838.7, 'target_text' => 'That\'s what\'s happening in Gaza.', 'source_text' => 'Itulah yang sedang menimpa saudara kita di Gaza.', 'order' => 231],
            ['start_time' => 838.8, 'end_time' => 843.16, 'target_text' => 'May Allah protect us and grant victory to our brothers and sisters.', 'source_text' => 'Semoga Allah melindungi kita semua dan mengurniakan kemenangan kepada saudara-saudari kita.', 'order' => 232],
            ['start_time' => 843.92, 'end_time' => 847.74, 'target_text' => 'So ask yourself when you see one another here in the masid, do I care?', 'source_text' => 'Oleh itu tanyalah diri anda apabila anda melihat satu sama lain di dalam masjid, adakah saya benar-benar peduli?', 'order' => 233],
            ['start_time' => 847.84, 'end_time' => 848.78, 'target_text' => 'Do I love?', 'source_text' => 'Adakah saya mengasihi?', 'order' => 234],
            ['start_time' => 848.88, 'end_time' => 849.66, 'target_text' => 'Do I feel?', 'source_text' => 'Adakah saya turut merasai kepedihan mereka?', 'order' => 235],
            ['start_time' => 849.76, 'end_time' => 850.7, 'target_text' => 'Would I save?', 'source_text' => 'Sanggupkah saya menyelamatkan mereka?', 'order' => 236],
            ['start_time' => 850.8, 'end_time' => 851.82, 'target_text' => 'Would I be there?', 'source_text' => 'Sanggupkah saya hadir menghulurkan bantuan?', 'order' => 237],
            ['start_time' => 851.92, 'end_time' => 852.7, 'target_text' => 'Offer respect.', 'source_text' => 'Berikanlah rasa hormat.', 'order' => 238],
            ['start_time' => 852.8, 'end_time' => 853.98, 'target_text' => 'Offer a greeting.', 'source_text' => 'Hulurkanlah salam.', 'order' => 239],
            ['start_time' => 854.08, 'end_time' => 855.82, 'target_text' => 'That greeting could be your paradise.', 'source_text' => 'Ucapan salam itulah yang mungkin menjadi asbab syurga anda.', 'order' => 240],
            ['start_time' => 855.92, 'end_time' => 856.38, 'target_text' => 'I see you.', 'source_text' => 'Saya melihat anda.', 'order' => 241],
            ['start_time' => 856.48, 'end_time' => 856.94, 'target_text' => 'I don\'t know you.', 'source_text' => 'Saya tidak mengenali anda.', 'order' => 242],
            ['start_time' => 857.04, 'end_time' => 857.66, 'target_text' => 'I love you.', 'source_text' => 'Saya tetap mengasihi anda.', 'order' => 243],
            ['start_time' => 857.76, 'end_time' => 858.54, 'target_text' => 'I care for you.', 'source_text' => 'Saya mengambil berat tentang anda.', 'order' => 244],
            ['start_time' => 858.64, 'end_time' => 860.3, 'target_text' => 'I I don\'t have a clue who you are.', 'source_text' => 'Saya tidak mengetahui langsung siapakah diri anda.', 'order' => 245],
            ['start_time' => 860.4, 'end_time' => 861.1, 'target_text' => 'That\'s irrelevant.', 'source_text' => 'Itu tidak penting sama sekali.', 'order' => 246],
            ['start_time' => 861.2, 'end_time' => 863.74, 'target_text' => 'You are here in the house of the Lord of the worlds.', 'source_text' => 'Anda kini berada di rumah Tuhan sekalian alam.', 'order' => 247],
            ['start_time' => 863.84, 'end_time' => 866.22, 'target_text' => 'It\'s not my house, not your, you are more than welcome.', 'source_text' => 'Ini bukan rumah saya, bukan rumah anda secara peribadi, anda amat dialu-alukan di sini.', 'order' => 248],
            ['start_time' => 866.32, 'end_time' => 870.78, 'target_text' => 'If I see something that perhaps is wrong, we will deal with it in a respectful manner.', 'source_text' => 'Jika saya melihat sesuatu yang mungkin salah, kita akan menanganinya dengan cara yang penuh hormat dan bijaksana.', 'order' => 249],
            ['start_time' => 870.88, 'end_time' => 874.22, 'target_text' => 'There was a youngster who walked into the masid with shorts.', 'source_text' => 'Pernah ada seorang pemuda yang melangkah masuk ke dalam masjid dengan memakai seluar pendek.', 'order' => 250],
            ['start_time' => 874.32, 'end_time' => 879.02, 'target_text' => 'And a guy came up, an elderly uncle who reads salah five times a day in the first S.', 'source_text' => 'Lalu datang seorang pakcik warga emas yang solat lima waktu setiap hari di saf paling hadapan.', 'order' => 251],
            ['start_time' => 879.12, 'end_time' => 884.22, 'target_text' => 'He came, he looked at him and started yelling and screaming, "You think you\'re going to dress?" He made such a mockery of', 'source_text' => 'Dia datang, memandang pemuda itu dan mula menjerit serta memarahinya, "Kamu rasa pakaian begini layak dipakai?" Dia memalukan dirinya sendiri,', 'order' => 252],
            ['start_time' => 884.32, 'end_time' => 888.78, 'target_text' => 'himself, but he insulted the young boy and kicked him out of the masid.', 'source_text' => 'malah dia menghina anak muda itu dan menghalaunya keluar dari masjid.', 'order' => 253],
            ['start_time' => 888.88, 'end_time' => 889.9, 'target_text' => 'And guess what?', 'source_text' => 'Dan cuba teka apa yang berlaku selepas itu?', 'order' => 254],
            ['start_time' => 890.0, 'end_time' => 892.7, 'target_text' => 'The youngster never returned to the masid again.', 'source_text' => 'Anak muda tersebut tidak pernah menjejakkan kakinya lagi ke masjid itu.', 'order' => 255],
            ['start_time' => 892.8, 'end_time' => 895.02, 'target_text' => 'And I\'m thinking to myself, is this how you solve the problem?', 'source_text' => 'Dan saya berfikir dalam hati, adakah begini cara kita menyelesaikan masalah?', 'order' => 256],
            ['start_time' => 895.12, 'end_time' => 899.02, 'target_text' => 'The father came to talk to me and he tells me, would you mind speaking to my son?', 'source_text' => 'Bapanya datang menemui saya dan meminta, "Bolehkah tuan tolong nasihatkan anak saya?"', 'order' => 257],
            ['start_time' => 899.12, 'end_time' => 899.98, 'target_text' => 'I went to speak to him.', 'source_text' => 'Saya pun pergi bercakap dengan pemuda itu.', 'order' => 258],
            ['start_time' => 900.08, 'end_time' => 900.78, 'target_text' => 'He says, "You know what?', 'source_text' => 'Dia berkata, "Tuan tahu apa?', 'order' => 259],
            ['start_time' => 900.88, 'end_time' => 903.58, 'target_text' => 'I came that day to cry to Allah for forgiveness.', 'source_text' => 'Hari itu saya datang ke masjid untuk menangis memohon keampunan kepada Allah.', 'order' => 260],
            ['start_time' => 903.68, 'end_time' => 906.22, 'target_text' => 'I have been a person very very astray.', 'source_text' => 'Sebelum ini hidup saya sangat tersesat dan jauh daripada agama.', 'order' => 261],
            ['start_time' => 906.32, 'end_time' => 908.14, 'target_text' => 'How am I supposed to know the etiquets?', 'source_text' => 'Bagaimanakah saya boleh tahu tentang adab dan etika berpakaian di masjid?', 'order' => 262],
            ['start_time' => 908.24, 'end_time' => 911.5, 'target_text' => 'It would have been good if someone came to me and told me, you know what?', 'source_text' => 'Alangkah baiknya jika ada seseorang datang kepada saya dengan sopan dan berkata,', 'order' => 263],
            ['start_time' => 911.6, 'end_time' => 916.94, 'target_text' => 'Uh here\'s a pair of whatever you can wear it or maybe perhaps let\'s do this or whatever else.', 'source_text' => '"Nah, ini ada kain pelikat atau seluar panjang yang boleh anda pakai, atau mari kita betulkan bersama-sama."', 'order' => 264],
            ['start_time' => 917.04, 'end_time' => 918.78, 'target_text' => 'Honor explain to me.', 'source_text' => 'Hormatilah saya dan terangkan dengan cara baik kepada saya.', 'order' => 265],
            ['start_time' => 918.88, 'end_time' => 921.66, 'target_text' => 'I said listen son, excuse the old man.', 'source_text' => 'Saya berkata, dengarlah anakku, maafkanlah pakcik tua itu.', 'order' => 266],
            ['start_time' => 921.76, 'end_time' => 927.58, 'target_text' => 'He probably didn\'t realize he hasn\'t interacted with people enough to know that this can happen.', 'source_text' => 'Dia mungkin tidak sedar dan kurang bergaul dengan orang ramai sehingga tidak faham situasi seperti ini boleh berlaku.', 'order' => 267],
            ['start_time' => 927.68, 'end_time' => 929.74, 'target_text' => 'But I want to give you an example of the prophet.', 'source_text' => 'Tetapi saya mahu kongsikan kepada kamu contoh teladan daripada Rasulullah SAW.', 'order' => 268],
            ['start_time' => 929.84, 'end_time' => 931.18, 'target_text' => 'Don\'t we say we love the prophet?', 'source_text' => 'Bukankah kita sering menyatakan bahawa kita mencintai Rasulullah?', 'order' => 269],
            ['start_time' => 931.28, 'end_time' => 933.18, 'target_text' => 'We follow the prophet peace be upon him.', 'source_text' => 'Kita mengikuti sunnah Rasulullah SAW.', 'order' => 270],
            ['start_time' => 933.28, 'end_time' => 934.6, 'target_text' => 'He respected everybody.', 'source_text' => 'Baginda sentiasa menghormati setiap manusia.', 'order' => 271],
            ['start_time' => 934.7, 'end_time' => 938.14, 'target_text' => '[clears throat] He respected even those who disagreed with him.', 'source_text' => '[berdehem] Baginda tetap menghormati mereka yang berbeza pendapat dengan baginda.', 'order' => 272],
            ['start_time' => 938.24, 'end_time' => 942.86, 'target_text' => 'Those who fought him, there was a level of honor and respect on the battlefield.', 'source_text' => 'Malah terhadap mereka yang memeranginya sekalipun, baginda tetap menjaga kehormatan dan etika di medan perang.', 'order' => 273],
            ['start_time' => 942.96, 'end_time' => 947.18, 'target_text' => 'He taught justice and he said, "Don\'t dishonor and disrespect the guys.', 'source_text' => 'Baginda mengajar keadilan dan bersabda, "Jangan mengaibkan dan merendahkan maruah mereka.', 'order' => 274],
            ['start_time' => 947.28, 'end_time' => 950.3, 'target_text' => 'We\'re fighting them for a case, we will leave the fight here.', 'source_text' => 'Kita memerangi mereka atas sebab mempertahankan kebenaran, dan kita tamatkan peperangan setakat di medan ini sahaja.', 'order' => 275],
            ['start_time' => 950.4, 'end_time' => 956.06, 'target_text' => 'The minute they want to utter shahada or they want to surrender or whatever else it was at the time of war, we will accept', 'source_text' => 'Saat mereka mahu mengucapkan dua kalimah syahadah atau menyerah kalah di waktu perang, kita akan terima', 'order' => 276],
            ['start_time' => 956.16, 'end_time' => 962.3, 'target_text' => 'it and we will honor it." That\'s why they made relations with those whom they were enemies with before.', 'source_text' => 'pengakuan itu dan kita hormati maruah mereka." Itulah sebabnya para sahabat membina hubungan baik dengan mereka yang dahulunya menjadi musuh ketat.', 'order' => 277],
            ['start_time' => 962.4, 'end_time' => 965.0, 'target_text' => 'Allah says it in the Quran.', 'source_text' => 'Allah SWT telah menegaskan hal ini di dalam Al-Quran.', 'order' => 278],
            ['start_time' => 971.2, 'end_time' => 975.9, 'target_text' => 'Allah is all capable, all able to create love between you and the one you hate.', 'source_text' => 'Allah Maha Berkuasa menumbuhkan rasa kasih sayang antara kamu dengan orang yang pernah kamu benci.', 'order' => 279],
            ['start_time' => 976.0, 'end_time' => 977.9, 'target_text' => 'Today you hate someone.', 'source_text' => 'Hari ini mungkin anda membenci seseorang.', 'order' => 280],
            ['start_time' => 978.0, 'end_time' => 984.14, 'target_text' => 'Allah says, "I can create love in a splash." Abu Sufyan came the victory of Mecca.', 'source_text' => 'Allah berfirman bahawa Dia mampu mencipta kasih sayang dalam sekelip mata. Lihatlah peristiwa Abu Sufyan ketika pembukaan Kota Makkah.', 'order' => 281],
            ['start_time' => 984.24, 'end_time' => 987.82, 'target_text' => 'He was the one who led the armies of the Kufar against the Muslim.', 'source_text' => 'Dialah pemimpin utama tentera kaum kafir yang menentang kaum Muslimin sebelum itu.', 'order' => 282],
            ['start_time' => 987.92, 'end_time' => 988.78, 'target_text' => 'Guess what happened?', 'source_text' => 'Teka apa yang berlaku kemudian?', 'order' => 283],
            ['start_time' => 988.88, 'end_time' => 990.62, 'target_text' => 'He just had to utter his shahada.', 'source_text' => 'Dia hanya perlu mengikrarkan dua kalimah syahadahnya.', 'order' => 284],
            ['start_time' => 990.72, 'end_time' => 997.18, 'target_text' => 'And the prophet wasallam says, "Whoever enters the house of Abu Sufyan is safe." 5 seconds ago, he himself was not safe.', 'source_text' => 'Dan Rasulullah SAW bersabda, "Sesiapa yang memasuki rumah Abu Sufyan, maka dia selamat." Padahal lima saat sebelumnya, dirinya sendiri belum terjamin keselamatannya.', 'order' => 285],
            ['start_time' => 997.28, 'end_time' => 998.06, 'target_text' => 'How\'s that?', 'source_text' => 'Tidakkah itu luar biasa?', 'order' => 286],
            ['start_time' => 998.16, 'end_time' => 1000.06, 'target_text' => 'May Allah subhanahu wa ta\'ala grant us ease.', 'source_text' => 'Semoga Allah Subhanahu Wata\'ala mengurniakan kemudahan dan kelapangan kepada kita.', 'order' => 287],
            ['start_time' => 1000.16, 'end_time' => 1006.54, 'target_text' => 'So I told the youngster, I says, "The same prophet, peace be upon him, when someone came into the masid and urinated, what', 'source_text' => 'Jadi saya beritahu pemuda itu, "Nabi yang sama SAW, ketika ada seorang Badwi masuk ke dalam masjid dan kencing di situ, apa', 'order' => 288],
            ['start_time' => 1006.64, 'end_time' => 1008.3, 'target_text' => 'you did was not even urination.', 'source_text' => 'yang kamu lakukan langsung tidak seburuk perbuatan kencing itu.', 'order' => 289],
            ['start_time' => 1008.4, 'end_time' => 1009.74, 'target_text' => 'The guy came in with a shorts.', 'source_text' => 'Kamu cuma masuk dengan memakai seluar pendek.', 'order' => 290],
            ['start_time' => 1009.84, 'end_time' => 1010.62, 'target_text' => 'It\'s I agree.', 'source_text' => 'Saya akui dan bersetuju.', 'order' => 291],
            ['start_time' => 1010.72, 'end_time' => 1013.98, 'target_text' => 'In Islam, you\'re supposed to cover your knees at least and bring it a bit lower.', 'source_text' => 'Di dalam Islam, anda sepatutnya menutup aurat sekurang-kurangnya menutup lutut dan melebihi sedikit ke bawah.', 'order' => 292],
            ['start_time' => 1014.08, 'end_time' => 1020.06, 'target_text' => 'And when you come to the house of Allah, it\'s more encouraged to come with something much more than the bare minimum.', 'source_text' => 'Dan apabila anda melangkah ke rumah Allah, amatlah dituntut untuk memakai pakaian yang jauh lebih sopan berbanding had aurat minimum.', 'order' => 293],
            ['start_time' => 1020.16, 'end_time' => 1022.86, 'target_text' => 'You see the bare minimum is navl to knee for a male.', 'source_text' => 'Batas aurat minimum bagi seorang lelaki adalah antara pusat hingga ke lutut.', 'order' => 294],
            ['start_time' => 1022.96, 'end_time' => 1025.58, 'target_text' => 'Imagine if all of us came with three quarters and we jumped in here.', 'source_text' => 'Bayangkan jika kita semua datang solat dengan berseluar tiga suku dan terus masuk ke sini.', 'order' => 295],
            ['start_time' => 1025.68, 'end_time' => 1027.02, 'target_text' => 'Salah is still makru.', 'source_text' => 'Solat dalam keadaan sedemikian tetap makruh hukumnya.', 'order' => 296],
            ['start_time' => 1027.12, 'end_time' => 1028.54, 'target_text' => 'Makru meaning it\'s detested.', 'source_text' => 'Makruh bermaksud perkara yang tidak disukai dalam syariat.', 'order' => 297],
            ['start_time' => 1028.64, 'end_time' => 1030.94, 'target_text' => 'You come into the house of Allah, wear something honorable.', 'source_text' => 'Apabila anda hadir ke rumah Allah, pakailah pakaian yang mulia dan terhormat.', 'order' => 298],
            ['start_time' => 1031.04, 'end_time' => 1034.54, 'target_text' => 'You were going to meet a leader or a millionaire or perhaps a president.', 'source_text' => 'Jika anda mahu bertemu dengan seorang pemimpin, jutawan, ataupun seorang presiden,', 'order' => 299],
            ['start_time' => 1034.64, 'end_time' => 1038.78, 'target_text' => 'You\'re not going to just pitch up in the shorts and say, "Hey, how\'s it guy?" That\'s not how it works.', 'source_text' => 'anda pasti tidak akan sekadar berbaju seluar pendek dan menyapa secara sambil lewa, bukan begitu caranya.', 'order' => 300],
            ['start_time' => 1038.88, 'end_time' => 1046.78, 'target_text' => 'You have to be reasonable and you have to understand that Allah Almighty deserves that honor and respect beyond this point.', 'source_text' => 'Anda perlu bersikap munasabah dan anda harus faham bahawa Allah Yang Maha Kuasa berhak menerima kemuliaan dan penghormatan melebihi segalanya.', 'order' => 301],
            ['start_time' => 1046.88, 'end_time' => 1053.82, 'target_text' => 'So my beloved brothers, I told him when this youngster peed in the masid, the prophet peace be upon him had to address the', 'source_text' => 'Maka wahai saudaraku yang dikasihi, saya beritahu pemuda itu bahawa ketika orang Badwi kencing di masjid, Rasulullah SAW terpaksa menegur para', 'order' => 302],
            ['start_time' => 1053.92, 'end_time' => 1060.78, 'target_text' => 'companions who were trying to STOP HIM WHILE HE WAS peeing and says no, let him finish what he\'s doing.', 'source_text' => 'sahabat yang cuba menghalangnya sedang dia membuang air kecil, dan bersabda jangan begitu, biarkan dia menghabiskan hajatnya.', 'order' => 303],
            ['start_time' => 1060.88, 'end_time' => 1062.06, 'target_text' => 'How can you do that?', 'source_text' => 'Bagaimanakah anda boleh buat demikian?', 'order' => 304],
            ['start_time' => 1062.16, 'end_time' => 1066.06, 'target_text' => 'But the idea is the mercy of Islam is look the pee is already there.', 'source_text' => 'Tetapi hikmah di sebalik rahmat Islam ialah, air kencing itu sudah pun tertumpah di situ.', 'order' => 305],
            ['start_time' => 1066.16, 'end_time' => 1067.18, 'target_text' => 'It\'s going to be a little bit more.', 'source_text' => 'Paling tidak pun ia akan bertambah sedikit lagi.', 'order' => 306],
            ['start_time' => 1067.28, 'end_time' => 1073.18, 'target_text' => 'But to stop a guy halfway through his pee, I\'ve always thought about it and said just imagine halfway through your pee, someone', 'source_text' => 'Tetapi untuk memberhentikan seseorang di pertengahan hajatnya, saya sering memikirkan hal itu dan berkata cuba bayangkan di pertengahan anda membuang air kecil, tiba-tiba seseorang', 'order' => 307],
            ['start_time' => 1073.28, 'end_time' => 1074.38, 'target_text' => 'say stop.', 'source_text' => 'menjerit berhenti.', 'order' => 308],
            ['start_time' => 1074.48, 'end_time' => 1075.5, 'target_text' => 'How are you going to do that?', 'source_text' => 'Bagaimanakah anda hendak menahannya?', 'order' => 309],
            ['start_time' => 1075.6, 'end_time' => 1078.78, 'target_text' => 'Come on, you\'re going to need to have a solid sphincter.', 'source_text' => 'Fikirkanlah, anda pasti memerlukan otot sfinkter yang sangat kuat.', 'order' => 310],
            ['start_time' => 1078.88, 'end_time' => 1080.54, 'target_text' => 'May Allah forgive us.', 'source_text' => 'Semoga Allah mengampunkan kita semua.', 'order' => 311],
            ['start_time' => 1080.64, 'end_time' => 1086.86, 'target_text' => 'But at the same time, as soon as he finished and while he was still almost finishing, the prophet sallallahu alaihi wasallam', 'source_text' => 'Namun pada masa yang sama, sebaik sahaja orang itu selesai dan ketika dia hampir menamatkan hajatnya, Rasulullah SAW', 'order' => 312],
            ['start_time' => 1086.96, 'end_time' => 1093.42, 'target_text' => 'tells his companions, "Go and fetch water in a bucket and bring it here." As they busy themselves getting the water, he says,', 'source_text' => 'berpesan kepada para sahabatnya, "Pergilah ambil sebaldi air dan bawakan ke mari." Sedang mereka sibuk mengambil air, baginda bersabda,', 'order' => 313],
            ['start_time' => 1093.52, 'end_time' => 1095.74, 'target_text' => '"Hey, this is the house of Allah.', 'source_text' => '"Wahai saudaraku, sesungguhnya ini adalah rumah Allah.', 'order' => 314],
            ['start_time' => 1095.84, 'end_time' => 1099.5, 'target_text' => 'It is for the for prayer, for Quran, for worship.', 'source_text' => 'Ia dibina untuk solat, membaca Al-Quran, dan beribadah.', 'order' => 315],
            ['start_time' => 1099.6, 'end_time' => 1106.86, 'target_text' => 'It\'s not for this type of thing." and he was about to be beaten by the companions and suddenly he\'s being spoken to with utmost', 'source_text' => 'Ia sama sekali bukan untuk perkara sebegini." Bayangkan dia hampir dipukul oleh para sahabat dan tiba-tiba dia ditegur dengan penuh', 'order' => 316],
            ['start_time' => 1106.96, 'end_time' => 1107.66, 'target_text' => 'respect.', 'source_text' => 'kelembutan dan rasa hormat.', 'order' => 317],
            ['start_time' => 1107.76, 'end_time' => 1116.62, 'target_text' => 'That respect was so beautiful respecting a person who did something that would not be accepted in our societies.', 'source_text' => 'Penghormatan itu sangat indah, memuliakan seseorang yang melakukan perkara yang langsung tidak dapat diterima dalam masyarakat kita.', 'order' => 318],
            ['start_time' => 1116.72, 'end_time' => 1117.66, 'target_text' => 'Totally.', 'source_text' => 'Sama sekali tidak.', 'order' => 319],
            ['start_time' => 1117.76, 'end_time' => 1121.18, 'target_text' => 'Imagine I can\'t imagine someone come to our masid and do this.', 'source_text' => 'Bayangkanlah, saya tidak dapat bayangkan jika ada seseorang datang ke masjid kita hari ini dan melakukan perkara tersebut.', 'order' => 320],
            ['start_time' => 1121.28, 'end_time' => 1127.02, 'target_text' => 'And in fact, obviously, we wouldn\'t want it to ever happen because now we we\'ve arrived at a level of education where you', 'source_text' => 'Dan hakikatnya sudah tentu kita tidak mahu perkara sedemikian berlaku kerana hari ini kita telah mencapai tahap pendidikan di mana anda', 'order' => 321],
            ['start_time' => 1127.12, 'end_time' => 1132.94, 'target_text' => 'would know, even if I walked into a church or a synagogue, I\'m not allowed as a Muslim to desecrate other people\'s places', 'source_text' => 'sudah maklum, bahkan jika saya masuk ke gereja atau rumah ibadat agama lain sekalipun, saya sebagai seorang Muslim dilarang mencemarkan rumah', 'order' => 322],
            ['start_time' => 1133.04, 'end_time' => 1134.46, 'target_text' => 'of worship.', 'source_text' => 'ibadat orang lain.', 'order' => 323],
            ['start_time' => 1134.56, 'end_time' => 1136.06, 'target_text' => 'So now I tell you something.', 'source_text' => 'Sekarang saya mahu beritahu anda sesuatu perkara.', 'order' => 324],
            ['start_time' => 1136.16, 'end_time' => 1138.2, 'target_text' => 'He says,', 'source_text' => 'Pemuda Badwi itu berkata,', 'order' => 325],
            ['start_time' => 1143.84, 'end_time' => 1148.38, 'target_text' => 'he saw the contrast between what the companions were doing and the prophet sallallahu alaihi wasallam came and spoke to him', 'source_text' => 'dia melihat perbezaan yang amat ketara antara tindakan para sahabat dengan cara Rasulullah SAW yang mendekatinya dan berbicara dengannya', 'order' => 326],
            ['start_time' => 1148.48, 'end_time' => 1149.42, 'target_text' => 'with love and care.', 'source_text' => 'dengan penuh kasih sayang dan perhatian.', 'order' => 327],
            ['start_time' => 1149.52, 'end_time' => 1155.42, 'target_text' => 'He explained he says, "Oh Allah, have mercy on me and Muhammad sallallahu alaihi wasallam and don\'t have mercy on anybody', 'source_text' => 'Maka dia berdoa dengan berkata, "Ya Allah, rahmatilah daku dan Muhammad SAW, dan janganlah Engkau merahmati sesiapa pun', 'order' => 328],
            ['start_time' => 1155.52, 'end_time' => 1159.98, 'target_text' => 'else." Hey, that means now he\'s telling you clearly what they did was wrong.', 'source_text' => 'selain kami berdua." Nampak tak, itu menunjukkan betapa dia merasakan tindakan para sahabat tadi tidak menyenangkan hatinya.', 'order' => 329],
            ['start_time' => 1160.08, 'end_time' => 1164.38, 'target_text' => 'What this teaching is is heavenly divine.', 'source_text' => 'Betapa ajaran akhlak baginda ini benar-benar bersumberkan wahyu ketuhanan yang mulia.', 'order' => 330],
            ['start_time' => 1164.48, 'end_time' => 1170.62, 'target_text' => 'So the prophet sallallahu alaihi wasallam says to him, "Hey, you are trying to make narrow something that doesn\'t become narrow."', 'source_text' => 'Maka Rasulullah SAW bersabda kepadanya, "Wahai sahabat, engkau cuba menyempitkan sesuatu yang amat luas."', 'order' => 331],
            ['start_time' => 1170.72, 'end_time' => 1171.12, 'target_text' => 'What is that?', 'source_text' => 'Apakah perkara yang luas itu?', 'order' => 332],
            ['start_time' => 1171.2, 'end_time' => 1172.22, 'target_text' => 'The mercy of Allah.', 'source_text' => 'Rahmat Allah SWT.', 'order' => 333],
            ['start_time' => 1172.32, 'end_time' => 1174.62, 'target_text' => 'Mercy of Allah encompasses everyone.', 'source_text' => 'Rahmat Allah itu meliputi dan merangkumi seluruh makhluk-Nya.', 'order' => 334],
            ['start_time' => 1174.72, 'end_time' => 1180.62, 'target_text' => 'No matter what you\'ve done, my brothers, my sisters, the mercy of Allah is very, very close.', 'source_text' => 'Walau apa pun kesilapan yang pernah anda lakukan, saudaraku dan saudariku, rahmat Allah amat hampir dengan kita.', 'order' => 335],
            ['start_time' => 1180.72, 'end_time' => 1185.5, 'target_text' => 'The victory that Allah will grant you is just at the doorstep.', 'source_text' => 'Kemenangan dan jalan keluar yang bakal Allah kurniakan kepada anda sudah pun berada di hadapan pintu.', 'order' => 336],
            ['start_time' => 1185.6, 'end_time' => 1189.5, 'target_text' => 'And don\'t ever lose your sabur, your patience.', 'source_text' => 'Dan jangan sesekali anda kehilangan sifat sabar anda.', 'order' => 337],
            ['start_time' => 1189.6, 'end_time' => 1194.38, 'target_text' => 'Don\'t ever become distant from Allah because of your problem, your hardship.', 'source_text' => 'Jangan pernah anda menjauhkan diri daripada Allah hanya kerana masalah atau kepayahan yang sedang anda hadapi.', 'order' => 338],
            ['start_time' => 1194.48, 'end_time' => 1196.22, 'target_text' => 'The door might seem closed.', 'source_text' => 'Pintu rahmat itu mungkin kelihatan seolah-olah tertutup.', 'order' => 339],
            ['start_time' => 1196.32, 'end_time' => 1198.46, 'target_text' => 'Keep knocking and remain steadfast.', 'source_text' => 'Teruskan mengetuk pintu itu dan kekallah istiqamah serta teguh.', 'order' => 340],
